import { describe, expect, it } from 'vitest';
import { parseXzHeaders } from './xz-header-inspector.utils.js';

// Generated by xz 5.8.2 from "XZ header fixture\\n". They exercise the
// on-disk Block layout including flags 0xC0, Block Padding, and each Check.
const CRC32_FIXTURE = new Uint8Array([
  0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00, 0x00, 0x01, 0x69, 0x22, 0xde, 0x36,
  0x04, 0xc0, 0x16, 0x12, 0x21, 0x01, 0x16, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0xa7, 0x51, 0x77, 0x9e, 0x01, 0x00, 0x11, 0x58,
  0x5a, 0x20, 0x68, 0x65, 0x61, 0x64, 0x65, 0x72, 0x20, 0x66, 0x69, 0x78,
  0x74, 0x75, 0x72, 0x65, 0x0a, 0x00, 0x00, 0x00, 0xa1, 0x37, 0x14, 0xb7,
  0x00, 0x01, 0x2e, 0x12, 0x4f, 0xcd, 0x38, 0xd8, 0x90, 0x42, 0x99, 0x0d,
  0x01, 0x00, 0x00, 0x00, 0x00, 0x01, 0x59, 0x5a,
]);

const CRC64_FIXTURE = new Uint8Array([
  0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00, 0x00, 0x04, 0xe6, 0xd6, 0xb4, 0x46,
  0x04, 0xc0, 0x16, 0x12, 0x21, 0x01, 0x16, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0xa7, 0x51, 0x77, 0x9e, 0x01, 0x00, 0x11, 0x58,
  0x5a, 0x20, 0x68, 0x65, 0x61, 0x64, 0x65, 0x72, 0x20, 0x66, 0x69, 0x78,
  0x74, 0x75, 0x72, 0x65, 0x0a, 0x00, 0x00, 0x00, 0x12, 0x46, 0xee, 0xc6,
  0xa2, 0x6d, 0x51, 0xce, 0x00, 0x01, 0x32, 0x12, 0x12, 0x90, 0x4f, 0x3e,
  0x1f, 0xb6, 0xf3, 0x7d, 0x01, 0x00, 0x00, 0x00, 0x00, 0x04, 0x59, 0x5a,
]);

describe('parseXzHeaders', () => {
  it('parses a real CRC32 XZ stream with size fields and Block Padding', () => {
    const result = parseXzHeaders(CRC32_FIXTURE);
    expect(result.blocks).toHaveLength(1);
    expect(result.blocks[0].flags).toBe(0xc0);
    expect(result.blocks[0].compressedSize).toBe(22n);
    expect(result.blocks[0].uncompressedSize).toBe(18n);
    expect(result.blocks[0].payloadSize).toBe(22n);
    expect(result.blocks[0].filters[0].id).toBe(33n);
    expect(result.index.records[0].unpaddedSize).toBe(46n);
    expect(result.index.records[0].uncompressedSize).toBe(18n);
    expect(result.streamHeader.checkSize).toBe(4);
  });

  it('parses a real CRC64 XZ stream with its eight-byte Check', () => {
    const result = parseXzHeaders(CRC64_FIXTURE);
    expect(result.blocks[0].payloadSize).toBe(22n);
    expect(result.index.records[0].unpaddedSize).toBe(50n);
    expect(result.streamHeader.checkName).toBe('CRC64');
    expect(result.streamHeader.checkSize).toBe(8);
    expect(result.streamFooter.checkId).toBe(4);
  });

  it('reports a truncated header clearly', () => {
    expect(() => parseXzHeaders(new Uint8Array([0xfd, 0x37]))).toThrow(
      /shorter than|required header/i
    );
  });

  it('rejects bad magic bytes', () => {
    const input = CRC32_FIXTURE.slice(); input[0] = 0;
    expect(() => parseXzHeaders(input)).toThrow(/bad Stream Header magic/i);
  });

  it('rejects a Block Padding byte before reading the Check field', () => {
    const input = CRC32_FIXTURE.slice(); input[54] = 1;
    expect(() => parseXzHeaders(input)).toThrow(/Block 1 padding/i);
  });
});
